head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil40209";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil40209.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_ApplyJoin_onclick
 * @description 「가입신청」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ApplyJoin_onclick = async function(e){
    try {
        await scwin.applyJoin()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil40209.btn_ApplyJoin_onclick' }); }
};

/**
 * @method
 * @name btn_GoURL_onclick
 * @description 「취소」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_GoURL_onclick = function(e){
    try {
        scwin.goURL('cancel')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil40209.btn_GoURL_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_ApplyJoin
 * @description Apply Join 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ApplyJoin = async function () {
    const sbmOptions = {
        id: "tx_fn_ApplyJoin",
        method: "post",
        action: "/outer/benfcertApct.do",
        ref: "dma_ApplyJoinReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name goURL
 * @description go URL 처리
 * @param {*} _target _target
 * @returns {void}
 * @hidden N
 */
scwin.goURL = function (_target) {
    let linkUrl;
    if (_target === 'cancel') {
        linkUrl = '/';
    }
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.setPageFrameSrc($c.win.getFrame(), (function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(linkUrl));
};

/**
 * @method
 * @name applyJoin
 * @description apply Join 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.applyJoin = async function () {
    const frm = (document.benfcertForm || { elements: [] });
    if (await scwin.checkRequired($c.util.getComponent('slc_benfcertApctTpCd'))) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_corpRegNo'))) {
        return;
    }
    if ($c.util.getComponent('ipt_corpRegNo').getValue().length !== 13) {
        await $c.win.alert(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))($c.util.getComponent('ipt_corpRegNo')) + '는 13자리입니다.');
        $c.util.getComponent("ipt_corpRegNo").focus();
        return;
    }
    if (!(scwin.isNumberInput($c.util.getComponent('ipt_corpRegNo')))) {
        await $c.win.alert('법인등록번호는 숫자만 입력하세요');
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_bzRegNo'))) {
        return;
    }
    if ($c.util.getComponent('ipt_bzRegNo').getValue().length !== 10) {
        await $c.win.alert(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))($c.util.getComponent('ipt_bzRegNo')) + '는 10자리입니다.');
        $c.util.getComponent("ipt_bzRegNo").focus();
        return;
    }
    if (!(scwin.isNumberInput($c.util.getComponent('ipt_bzRegNo')))) {
        await $c.win.alert('사업자등록번호는 숫자만 입력하세요');
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_corpNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "회사명"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_corpNm'))) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_corpEngNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "회사영문명"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_corpEngNm'))) {
        return;
    }
    $c.util.getComponent('dma_ApplyJoinReq').set('method', 'registerBenfcertApct');
    frm.action = '/outer/benfcertApct.do';
    const nr = await scwin.tx_fn_ApplyJoin();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/message/message.xml", { "method": 'registerBenfcertApct' });
    }
};

/**
 * @method
 * @name checkRequired
 * @description 필수 입력 검사 — 값이 비면 항목명으로 알리고 포커스를 준 뒤 true(as-is fn_NullChk/fn_IsNull 의미 보존 · pcc/fil 반입 후보)
 * @param {Object} comp 입력 컴포넌트
 * @param {*} fieldName 항목명(생략 시 컴포넌트 title → id)
 * @returns {Promise<Boolean>} 비어 있으면 true
 * @hidden N
 */
scwin.checkRequired = async function (comp, fieldName) {
    if (!comp || !$c.util.isEmpty($c.str.trim(String(comp.getValue() ?? "")))) { return false; }
    const name = fieldName || (typeof comp.getTitle === "function" && comp.getTitle()) || comp.getID();
    await $c.win.alert("'" + name + "' 항목을 입력하세요");
    comp.focus();
    return true;
};

/**
 * @method
 * @name isNumberInput
 * @description 숫자만 입력됐는지 검사 — 아니면 포커스를 주고 false(as-is fn_IsNumber 의미 보존 · pcc/fil 반입 후보)
 * @param {Object} comp 입력 컴포넌트
 * @returns {Boolean} 숫자(공백 제외)만이면 true
 * @hidden N
 */
scwin.isNumberInput = function (comp) {
    const v = String(comp.getValue() ?? "").replace(/\s/g, "");
    if (!/^\d*$/.test(v)) { comp.focus(); return false; }
    return true;
};
